"""Normalize release records and resolve release identity at the input boundary."""
import heapq


class JournalError(ValueError):
    pass


def _text(value):
    return isinstance(value, str) and value != ""


def _ids(value):
    """Validate an array of change ID strings, returning them as a list."""
    if not isinstance(value, list) or not all(_text(item) for item in value):
        raise JournalError("invalid-change")
    return list(value)


def read_changes(records):
    """Validate change records and collapse duplicate identities.

    Records with equal id, component, units and dependency set are duplicates
    and count once. Repeated IDs with different content conflict.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not _text(row.get("id"))
                or not _text(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = frozenset(_ids(row.get("depends_on", [])))
        identity = (row["id"], row["component"], row["units"], depends_on)
        if row["id"] in seen:
            if seen[row["id"]] != identity:
                raise JournalError("conflicting-change")
            continue
        seen[row["id"]] = identity
        changes.append({
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": depends_on,
        })
    return changes


def applied_ids(request):
    """Read the persisted release journal supplied by the caller."""
    return frozenset(_ids(request.get("applied", [])))


def order_changes(changes, applied):
    """Return the deterministic topological order of all known changes.

    Dependencies must name known changes and the applied journal may only name
    known changes; a cycle anywhere is fatal. Among currently eligible changes
    the lexicographically smallest ID is emitted first.
    """
    known = {row["id"] for row in changes}
    if not applied <= known:
        raise JournalError("unknown-dependency")
    for row in changes:
        if not row["depends_on"] <= known:
            raise JournalError("unknown-dependency")

    pending = {row["id"]: len(row["depends_on"]) for row in changes}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            dependents[dependency].append(row["id"])

    eligible = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        change_id = heapq.heappop(eligible)
        order.append(change_id)
        for dependents_id in dependents[change_id]:
            pending[dependents_id] -= 1
            if pending[dependents_id] == 0:
                heapq.heappush(eligible, dependents_id)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order

