    if not isinstance(value, list) or not all(_text(item) for item in value):
        raise JournalError("invalid-retain")
    return frozenset(value)


def retained_ids(request, applied):
    """Read the rollback ``retain`` list of change IDs to keep applied.

    ``retain`` defaults to empty, and because it only lists changes that are
    already applied it may only name journal entries. Malformed values and
    nonapplied IDs are rejected; closing over dependencies happens in the
    planner.
    """
    retain = _retain_ids(request.get("retain", []))
    if not retain <= applied:
        raise JournalError("invalid-retain")
