"""JSON transport for the release planner."""
import json
import sys

from planner import plan


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        # Transport only: malformed bytes/text never reach the planner.
        # UnicodeDecodeError is a ValueError, so bad encodings land here too.
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        result = plan(request)
    try:
        text = json.dumps(result, separators=(",", ":"))
    except (TypeError, ValueError):
        # Defensive: SPEC promises a JSON result for every request. A result
        # that cannot even be serialized must still collapse to an error
        # object rather than a traceback and a non-zero exit.
        text = json.dumps({"status": "error", "error": "invalid-request",
                           "actions": [], "units": 0}, separators=(",", ":"))
    print(text)


if __name__ == "__main__":
    main()

