    dead = set(retain)
    for change_id in retain:
        if change_id not in applied:
            # G2 change 3: the caller's intent is to keep something the
            # journal says is not deployed. Rolling back around that would
            # silently emit a list that contradicts the request.
            raise JournalError("invalid-retain")
    stack = list(retain)
    while stack:
        for dep in adjacency[stack.pop()]:
            if dep in applied and dep not in dead:
                # Applied-transitive dependent unfreezing: `order` is the full
                # topological order, so every applied dependency of a kept
                # change also needs to survive, otherwise the kept change
                # would be left without its own prerequisites.
                dead.add(dep)
