"""Compose policy and journal data into a plan.

Import direction is fixed by SPEC.md: planner may read journal and policy, but
neither may import planner. All domain failures are converted here into the
exact JSON error body, so callers never see a partial action list.
"""
import heapq

from journal import (JournalError, collapse_duplicates, read_applied, read_changes,
                     read_retain)
from policy import PolicyError, cap_for, limit_for


class PlanError(ValueError):
    pass


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(by_id):
    """Return every change ID in one deterministic execution order.

    Dependencies are validated first so a missing target or a bad applied ID is
    reported as unknown-dependency instead of silently becoming a root or a
    cycle. Among currently eligible nodes the lexicographically smallest ID is
    taken, so the order depends only on IDs, never on input order or dict order.
    """
    for change in by_id.values():
        for dependency in change["depends_on"]:
            if dependency not in by_id:
                raise PlanError("unknown-dependency")
    pending = {change_id: len(change["depends_on"]) for change_id, change in by_id.items()}
    dependents = {change_id: [] for change_id in by_id}
    for change in by_id.values():
        for dependency in change["depends_on"]:
            dependents[dependency].append(change["id"])
    ready = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(by_id):
        # Whatever is left still has an unmet dependency, and every unmet ID was
        # already proven to exist, so the remainder must form a cycle.
        raise PlanError("dependency-cycle")
    return order


def retained_with_dependencies(retained, by_id, live):
    """Grow ``retained`` to every applied change those IDs transitively need.

    CHANGE-G2.md line 7: a retained change must stay usable after rollback, so
    anything it depends on that is still applied has to stay too. Only applied
    dependencies are walked: unapplied nodes were never installed, are not
    rollback candidates, and following them would pull in nothing to keep. The
    graph is acyclic by the time this runs, but the visited set also guards
    against revisiting shared subtrees.
    """
    keep = set(retained)
    stack = list(retained)
    while stack:
        for dependency in by_id[stack.pop()]["depends_on"]:
            if dependency in live and dependency not in keep:
                keep.add(dependency)
                stack.append(dependency)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        by_id = collapse_duplicates(changes)
        order = topological_order(by_id)
        unknown = [change_id for change_id in applied if change_id not in by_id]
        if unknown:
            raise JournalError("unknown-dependency")
        action = request.get("action")
        if action == "rollback":
            # Rollback reverts from the end of the same full order, so execution
            # history is reproduced exactly; only applied changes are emitted
            # and the budget is validated above but never caps the result.
            # G2 retain narrows that set: retained IDs and their applied
            # transitive dependencies survive, everything else keeps the G1
            # reverse order.
            live = set(applied)
            keep = retained_with_dependencies(read_retain(request, applied), by_id, live)
            actions = [change_id for change_id in reversed(order)
                       if change_id in live and change_id not in keep]
        else:
            # Replay: applied changes already satisfy their dependents and are
            # not re-emitted, so they must not consume new budget either.
            done = set(applied)
            actions = [change_id for change_id in order if change_id not in done]
        units = sum(by_id[change_id]["units"] for change_id in actions)
        cap_for(request, budget, units)
    except (PolicyError, JournalError, PlanError) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

