    ids = {row["id"] for row in changes}
    dependents = {change_id: [] for change_id in ids}
    pending = {}
    for row in changes:
        links = set()
        for dependency in row["depends_on"]:
            if dependency not in ids:
                raise JournalError("unknown-dependency")
            links.add(dependency)
        pending[row["id"]] = len(links)
        for dependency in links:
            dependents[dependency].append(row["id"])
    ready = [change_id for change_id in dependents if pending[change_id] == 0]
    heapq.heapify(ready)
