planner.py.text:
"""Compose policy and journal data into a plan.

Dependency direction: planner depends on policy and journal; nothing depends
on planner except the transport entrypoint.

G2 (CHANGE-G2.md clause 3) puts the rollback ``retain`` closure here rather
than in journal.py: deciding which retained IDs are applied and which applied
dependencies they keep needs the graph *and* ``applied``, both of which live in
the planner.

Stable surface (used by release.py and pinned by tests):
    failure(code) -- the exact failure envelope
    plan(request) -- the exact success/failure envelope
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, budget_applies, effective_budget, limit_for


def failure(code):
    # Field order is part of the contract: status, error, actions, units.
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(actions, units):
    # Field order is part of the contract: status, actions, units.
    return {"status": "ok", "actions": list(actions), "units": units}


def _graph(changes):
    """Map each id to its dependency set, rejecting unknown targets."""
    ids = {row["id"] for row in changes}
    graph = {}
    for row in changes:
        deps = set(row["depends_on"])
        if deps - ids:
            # A dependency on an unknown change can never be satisfied, so it
            # is a data error rather than an ordering problem.
            raise JournalError("unknown-dependency")
        graph[row["id"]] = deps
    return graph


def topological_order(graph):
    """Deterministic topological order with lexicographic tie-breaking.

    Kahn's algorithm with a min-heap of currently eligible IDs. "Eligible" is
    recomputed as changes are emitted, which is what SPEC means by lexicographic
    tie-breaking among *currently* eligible changes -- not "sort everything by
    id after the fact", which could violate edges.

    Cycle detection reuses this single traversal: if fewer nodes are emitted
    than exist, the remaining nodes sit on or behind a cycle.
    """
    pending = {change_id: len(deps) for change_id, deps in graph.items()}
    dependents = {change_id: [] for change_id in graph}
    for change_id, deps in graph.items():
        for dependency in deps:
            dependents[dependency].append(change_id)
    ready = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(graph):
        raise JournalError("dependency-cycle")
    return order


def read_retain(value):
    """Validate the shape of the rollback ``retain`` list (clause 3).

    Missing ``retain`` means "retain nothing", i.e. the G1 behaviour. Returns a
    set of IDs; whether they are actually applied is a replay question checked
    by ``_check_retain``.
    """
    if value is None:
        return set()
    if not isinstance(value, list):
        raise JournalError("invalid-retain")
    retained = set()
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-retain")
        retained.add(item)
    return retained


def _check_retain(retained, applied):
    """Every retained ID must name a change that is already applied."""
    if retained - applied:
        raise JournalError("invalid-retain")


def rollback_closure(graph, applied, retained):
    """Applied IDs a rollback of ``retained`` must keep (clause 3).

    Starts from the retained IDs and walks dependencies transitively, keeping a
    dependency only when it is itself applied: an unapplied dependency is
    already absent from the rollback and keeping it would be a no-op.

    Retaining a change never drags in its dependents. A dependent may be rolled
    back even though its dependency stays -- that is the point of retaining:
    keep the foundation, release the rest.
    """
    needed = set()
    pending = list(retained)
    while pending:
        change_id = pending.pop()
        if change_id in needed or change_id not in applied:
            continue
        needed.add(change_id)
        pending.extend(graph[change_id])
    return needed


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy first: the environment gate (including G2's production freeze)
        # is settled before anything graph-shaped is touched.
        action, budget = limit_for(request)
